root = repo.list(".")

def walk(path, depth):
    out = []
    if depth > 4:
        return out
    entries = repo.list(path)
    for e in entries:
        p = path.rstrip("/") + "/" + e
        if e.endswith("/"):
            out.extend(walk(p, depth + 1))
        else:
            out.append(p)
    return out

tree = walk(".", 0)
tree = [p for p in tree if "target/" not in p]
return {"root_entries": root, "files": tree}

